import heapq


def dependency_solver(data, component_id):
    packages = data["packages"]
    names = sorted(packages)
    policy = {
        "component_01": (True, True),
        "component_02": (False, True),
        "component_03": (True, False),
        "component_04": (False, False),
        "component_05": (True, True),
    }
    maximize, descending = policy[component_id]
    order = sorted(names, reverse=descending)
    features = set(data.get("features", []))
    blocked = data.get("blocked", {})
    pins = data.get("pins", {})
    roots = data["roots"]
    rows = {name: {r["version"]: r for r in versions}
            for name, versions in packages.items()}
    best_vector = None
    best = None

    # Enumerate the small version/absence space and validate the resulting closure.
    choices = []
    for name in names:
        choices.append([-1] + [r["version"] for r in packages[name]])

    def examine(index, assignment):
        nonlocal best_vector, best
        if index < len(names):
            name = names[index]
            for version in choices[index]:
                assignment[name] = version
                examine(index + 1, assignment)
            assignment.pop(name, None)
            return

        for name, bounds in roots.items():
            v = assignment[name]
            if v < bounds[0] or v > bounds[1]:
                return
        edges = {}
        for name, v in assignment.items():
            if v == -1:
                continue
            if v in blocked.get(name, ()) or (name in pins and pins[name] != v):
                return
            deps = []
            for dep in rows[name][v].get("deps", []):
                feature = dep.get("feature", "")
                if feature and feature not in features:
                    continue
                other = dep["name"]
                ov = assignment[other]
                if ov < dep["min"] or ov > dep["max"]:
                    return
                deps.append(other)
            edges[name] = deps

        # All installed packages must be in the roots' active dependency closure.
        reached = set()
        stack = list(roots)
        while stack:
            name = stack.pop()
            if name in reached:
                continue
            reached.add(name)
            if assignment[name] == -1:
                return
            stack.extend(edges[name])
        if any(v != -1 and name not in reached
               for name, v in assignment.items()):
            return

        active, finished = set(), set()
        def visit(name):
            if name in active:
                return False
            if name in finished:
                return True
            active.add(name)
            for other in edges[name]:
                if not visit(other):
                    return False
            active.remove(name)
            finished.add(name)
            return True
        if not all(visit(name) for name in edges):
            return

        vector = tuple(assignment[n] for n in order)
        if best_vector is None or (vector > best_vector if maximize else vector < best_vector):
            best_vector = vector
            best = {n: v for n, v in assignment.items() if v != -1}

    examine(0, {})
    return {"versions": best} if best is not None else {"error": "unsatisfiable"}


def ledger(data):
    cutoff = data.get("cutoff", 10**9)
    winners = {}
    for pos, event in enumerate(data["events"]):
        if event.get("sequence", 0) > cutoff:
            continue
        key = event.get("id", "anonymous:" + str(pos))
        rank = (event.get("revision", 0), pos)
        if key not in winners or rank > winners[key][0]:
            winners[key] = (rank, event)

    balances = dict(data.get("opening", {}))
    mode = data["rounding"]
    def rounded(n, d):
        if mode == "half_up":
            return (n + d // 2) // d
        return n // d

    for _, event in winners.values():
        if event.get("void", False):
            continue
        raw = event["price"] * event.get("quantity", 1)
        discount = min(10000, max(0, event.get("discount_bp", 0)))
        net = rounded(raw * (10000 - discount), 10000)
        tax = rounded(raw * event.get("tax_bp", 0), 10000)
        total = net + tax
        if event.get("kind") == "refund":
            total = -total
        key = event.get("account", "default") + "|" + event.get("currency", "USD")
        balances[key] = balances.get(key, 0) + total
    return {"balances": balances}


def quota_intervals(data):
    jobs = data["jobs"]
    k = data["k"]
    blocked = set(data.get("blocked", []))
    mandatory = set(data.get("mandatory", []))
    quotas = data.get("quotas", {})
    available = [j for j in jobs if j["id"] not in blocked]
    by_id = {j["id"]: j for j in jobs}
    if not mandatory.issubset(by_id) or mandatory & blocked or len(available) < k:
        return {"error": "impossible"}
    best_value = None
    best_ids = None
    for subset in combinations(available, k):
        ids = [j["id"] for j in subset]
        if not mandatory.issubset(ids):
            continue
        counts = {}
        for j in subset:
            counts[j["group"]] = counts.get(j["group"], 0) + 1
        if any(not (bounds[0] <= counts.get(group, 0) <= bounds[1])
               for group, bounds in quotas.items()):
            continue
        ends = []
        valid = True
        for job in sorted(subset, key=lambda j: (j["start"], j["end"])):
            ends = [end for end in ends if end > job["start"]]
            ends.append(job["end"])
            if len(ends) > 2:
                valid = False
                break
        if not valid:
            continue
        ids.sort()
        value = sum(j["value"] for j in subset)
        if (best_value is None or value > best_value or
                (value == best_value and ids > best_ids)):
            best_value, best_ids = value, ids
    if best_value is None:
        return {"error": "impossible"}
    return {"selected": best_ids, "value": best_value}


def temporal_routes(data):
    required = data.get("required", [])
    bit = {node: 1 << i for i, node in enumerate(required)}
    full = (1 << len(required)) - 1
    graph = [[] for _ in range(data["n"])]
    for edge in data["edges"]:
        graph[edge["u"]].append(edge)

    source = data["source"]
    initial_mask = bit.get(source, 0)
    initial = (source, initial_mask, data["coupons"])
    start = data["start"]
    distances = {initial: start}
    queue = [(start, source, initial_mask, data["coupons"])]
    while queue:
        time, node, mask, remaining = heapq.heappop(queue)
        state = (node, mask, remaining)
        if distances.get(state) != time:
            continue
        if node == data["target"] and mask == full:
            return {"arrival": time}
        for edge in graph[node]:
            depart = max(time, edge["open"])
            if depart >= edge["close"]:
                continue
            options = [(edge["duration"], remaining)]
            if remaining:
                options.append((max(1, edge["duration"] - edge.get("discount", 0)), remaining - 1))
            for duration, left in options:
                arrival = depart + duration
                if arrival > data["deadline"]:
                    continue
                nxt = edge["v"]
                next_mask = mask | bit.get(nxt, 0)
                new_state = (nxt, next_mask, left)
                if arrival < distances.get(new_state, float("inf")):
                    distances[new_state] = arrival
                    heapq.heappush(queue, (arrival, nxt, next_mask, left))
    return {"arrival": None}


